/* ==UserStyle==
@name Scalar Catppuccin
@namespace github.com/catppuccin/userstyles/styles/scalar
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/scalar
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/scalar/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Ascalar
@description Soothing pastel theme for Scalar
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("scalar.com") {
  @import url("https://unpkg.com/@catppuccin/highlightjs@1.0.0/css/catppuccin-variables.important.css");
  code.hljs {
    background: none !important;
  }

  .light-mode {
    #catppuccin(@lightFlavor);
  }

  .dark-mode {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    --scalar-color-1: @text;
    --scalar-color-2: @subtext1;
    --scalar-color-3: @subtext0;
    --scalar-color-accent: @accent;
    --scalar-background-1: @base;
    --scalar-background-2: @surface0;
    --scalar-background-3: @surface1;
    --scalar-background-accent: fade(@accent, 12%);
    --scalar-border-color: @surface1;
    --scalar-color-green: @green;
    --scalar-color-red: @red;
    --scalar-color-yellow: @yellow;
    --scalar-color-blue: @blue;
    --scalar-color-orange: @peach;
    --scalar-color-purple: @mauve;
    --scalar-selection-1: fade(@accent, 30%);
    --scalar-button-1: @accent;
    --scalar-button-1-hover: darken(@accent, 5%);
    --scalar-button-1-color: @base;

    background-color: @base;

    .sidebar {
      --scalar-sidebar-background-1: @mantle;
      --scalar-sidebar-item-hover-background: @surface0;
      --scalar-sidebar-item-active-background: fade(@accent, 10%);
      --scalar-sidebar-color-active: @accent;
    }

    .scalar-code-block, .t-editor__code {
      background-color: @mantle;
    }

    .brightness-lifted {
      filter: none; // remove elevated filter on dropdown modal backgrounds
    }

    .text-white {
      color: @base; // danger (delete) button text
    }

    // https://scalar.com/
    .logo {
      filter: @text-filter;
    }
  }
}

